package io.github.freechat.android.core.network.pairing

import io.github.freechat.android.core.model.PairingLink
import java.net.URI
import java.net.URLDecoder
import java.nio.charset.StandardCharsets

/**
 * Parses the pairing deep link generated by the Dalamud plugin:
 *
 * freechat://pair?v=1&host=192.168.1.10&port=14777&sid=<id>&fp=<64 hex>&code=<6 digits>
 */
object PairingLinkParser {
    fun parse(value: String): PairingLink {
        val uri = try {
            URI(value.trim())
        } catch (error: Exception) {
            throw IllegalArgumentException("Invalid pairing link", error)
        }
        require(uri.scheme == "freechat" && uri.host == "pair") {
            "Pairing link must use freechat://pair"
        }

        val query = parseQuery(uri.rawQuery)
        val version = query["v"]?.toIntOrNull() ?: 1
        require(version == 1) { "Unsupported pairing link version: $version" }

        val host = query["host"]?.trim().orEmpty()
        require(host.isNotBlank()) { "Pairing link is missing host" }

        val port = query["port"]?.toIntOrNull()
            ?: throw IllegalArgumentException("Pairing link is missing port")
        require(port in 1..65535) { "Pairing link port is out of range" }

        val serverId = query["sid"]?.trim().orEmpty()
        require(serverId.isNotBlank()) { "Pairing link is missing server id" }

        val fingerprint = query["fp"]?.trim()?.lowercase().orEmpty()
        require(FINGERPRINT.matches(fingerprint)) { "Pairing link fingerprint is invalid" }

        val code = query["code"]?.trim()?.takeIf { it.isNotEmpty() }
        if (code != null) {
            require(CODE.matches(code)) { "Pairing code must be 6 digits" }
        }

        return PairingLink(
            host = host,
            port = port,
            serverId = serverId,
            fingerprintHex = fingerprint,
            code = code,
            protocolVersion = version,
        )
    }

    private fun parseQuery(rawQuery: String?): Map<String, String> {
        if (rawQuery.isNullOrBlank()) return emptyMap()
        return rawQuery.split('&')
            .filter { it.isNotBlank() }
            .associate { part ->
                val index = part.indexOf('=')
                if (index < 0) {
                    decode(part) to ""
                } else {
                    decode(part.substring(0, index)) to decode(part.substring(index + 1))
                }
            }
    }

    private fun decode(value: String): String =
        URLDecoder.decode(value, StandardCharsets.UTF_8.name())

    private val FINGERPRINT = Regex("^[0-9a-f]{64}$")
    private val CODE = Regex("^\\d{6}$")
}
